        assertEquals(
            "(" + i + ',' + j + ')',
            condition.isMasked(i, j),
            bits.get(j, i));
      }
    }
  }

  @FunctionalInterface
  private interface MaskCondition {
    boolean isMasked(int i, int j);
  }

}

