package com.google.zxing.pdf417.decoder;

import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;

import java.lang.reflect.Method;

/**
 * Tests {@link PDF417ScanningDecoder#getBarcodeMetadata}.
 */
public class PDF417ScanningDecoderTest extends Assert {

  private static Method getGetBarcodeMetadataMethod() throws NoSuchMethodException {
    return PDF417ScanningDecoder.class.getDeclaredMethod(
        "getBarcodeMetadata",
        DetectionResultRowIndicatorColumn.class,
        DetectionResultRowIndicatorColumn.class
    );
  }

  @SuppressWarnings("unchecked")
  private BarcodeMetadata invokeGetBarcodeMetadata(
          DetectionResultRowIndicatorColumn left,
          DetectionResultRowIndicatorColumn right) throws Exception {
    Method method = getGetBarcodeMetadataMethod();
    method.setAccessible(true);
    return (BarcodeMetadata) method.invoke(null, left, right);
  }

  /**
   * When only the column count differs between left and right metadata,
   * getBarcodeMetadata should return null (inconsistent metadata).
   * The bug uses && instead of ||, so it returns leftBarcodeMetadata instead.
   */
  @Test
  public void testGetBarcodeMetadataReturnsNullWhenOnlyColumnCountDiffers() throws Exception {
    BarcodeMetadata left = new BarcodeMetadata(10, 2, 2, 0); // columnCount=10, ecLevel=0, rowCount=4
    BarcodeMetadata right = new BarcodeMetadata(12, 2, 2, 0); // columnCount=12, ecLevel=0, rowCount=4

    DetectionResultRowIndicatorColumn leftCol = Mockito.mock(DetectionResultRowIndicatorColumn.class);
    DetectionResultRowIndicatorColumn rightCol = Mockito.mock(DetectionResultRowIndicatorColumn.class);
    Mockito.when(leftCol.getBarcodeMetadata()).thenReturn(left);
    Mockito.when(rightCol.getBarcodeMetadata()).thenReturn(right);

    // Correct behavior: return null when ANY field differs
    assertNull("getBarcodeMetadata should return null when columnCount differs",
        invokeGetBarcodeMetadata(leftCol, rightCol));
  }

  /**
   * When only the error correction level differs, getBarcodeMetadata should return null.
   */
  @Test
  public void testGetBarcodeMetadataReturnsNullWhenOnlyErrorCorrectionLevelDiffers() throws Exception {
    BarcodeMetadata left = new BarcodeMetadata(10, 2, 2, 0); // columnCount=10, ecLevel=0, rowCount=4
    BarcodeMetadata right = new BarcodeMetadata(10, 2, 2, 1); // columnCount=10, ecLevel=1, rowCount=4

    DetectionResultRowIndicatorColumn leftCol = Mockito.mock(DetectionResultRowIndicatorColumn.class);
    DetectionResultRowIndicatorColumn rightCol = Mockito.mock(DetectionResultRowIndicatorColumn.class);
    Mockito.when(leftCol.getBarcodeMetadata()).thenReturn(left);
    Mockito.when(rightCol.getBarcodeMetadata()).thenReturn(right);

    assertNull("getBarcodeMetadata should return null when errorCorrectionLevel differs",
        invokeGetBarcodeMetadata(leftCol, rightCol));
  }

  /**
   * When only the row count differs, getBarcodeMetadata should return null.
   */
  @Test
  public void testGetBarcodeMetadataReturnsNullWhenOnlyRowCountDiffers() throws Exception {
    BarcodeMetadata left = new BarcodeMetadata(10, 2, 2, 0); // columnCount=10, ecLevel=0, rowCount=4
    BarcodeMetadata right = new BarcodeMetadata(10, 3, 1, 0); // columnCount=10, ecLevel=0, rowCount=4... wait no: 3+1=4
    // Let me make rowCount actually differ
    // rowCount = rowCountUpperPart + rowCountLowerPart
    // left: 2+2=4, right: 3+2=5

    right = new BarcodeMetadata(10, 3, 2, 0); // columnCount=10, ecLevel=0, rowCount=5

    DetectionResultRowIndicatorColumn leftCol = Mockito.mock(DetectionResultRowIndicatorColumn.class);
    DetectionResultRowIndicatorColumn rightCol = Mockito.mock(DetectionResultRowIndicatorColumn.class);
    Mockito.when(leftCol.getBarcodeMetadata()).thenReturn(left);
    Mockito.when(rightCol.getBarcodeMetadata()).thenReturn(right);

    assertNull("getBarcodeMetadata should return null when rowCount differs",
        invokeGetBarcodeMetadata(leftCol, rightCol));
  }

  /**
   * When two fields differ (but not all three), getBarcodeMetadata should return null.
   */
  @Test
  public void testGetBarcodeMetadataReturnsNullWhenTwoFieldsDiffer() throws Exception {
    BarcodeMetadata left = new BarcodeMetadata(10, 2, 2, 0); // columnCount=10, ecLevel=0, rowCount=4
    BarcodeMetadata right = new BarcodeMetadata(12, 3, 2, 1); // columnCount=12, ecLevel=1, rowCount=5

    DetectionResultRowIndicatorColumn leftCol = Mockito.mock(DetectionResultRowIndicatorColumn.class);
    DetectionResultRowIndicatorColumn rightCol = Mockito.mock(DetectionResultRowIndicatorColumn.class);
    Mockito.when(leftCol.getBarcodeMetadata()).thenReturn(left);
    Mockito.when(rightCol.getBarcodeMetadata()).thenReturn(right);

    // With the bug (&&), this would return null because ALL three differ.
    // But we want to test: when ALL three differ, null is correct.
    assertNull("getBarcodeMetadata should return null when all three fields differ",
        invokeGetBarcodeMetadata(leftCol, rightCol));
  }

  /**
   * When all fields match, getBarcodeMetadata should return left metadata.
   */
  @Test
  public void testGetBarcodeMetadataReturnsLeftWhenAllFieldsMatch() throws Exception {
    BarcodeMetadata left = new BarcodeMetadata(10, 2, 2, 0);
    BarcodeMetadata right = new BarcodeMetadata(10, 2, 2, 0);

    DetectionResultRowIndicatorColumn leftCol = Mockito.mock(DetectionResultRowIndicatorColumn.class);
    DetectionResultRowIndicatorColumn rightCol = Mockito.mock(DetectionResultRowIndicatorColumn.class);
    Mockito.when(leftCol.getBarcodeMetadata()).thenReturn(left);
    Mockito.when(rightCol.getBarcodeMetadata()).thenReturn(right);

    assertEquals("getBarcodeMetadata should return left when all fields match",
        left, invokeGetBarcodeMetadata(leftCol, rightCol));
  }

  /**
   * When left is null, getBarcodeMetadata should return right metadata.
   */
  @Test
  public void testGetBarcodeMetadataReturnsRightWhenLeftIsNull() throws Exception {
    BarcodeMetadata right = new BarcodeMetadata(10, 2, 2, 0);

    DetectionResultRowIndicatorColumn leftCol = Mockito.mock(DetectionResultRowIndicatorColumn.class);
    DetectionResultRowIndicatorColumn rightCol = Mockito.mock(DetectionResultRowIndicatorColumn.class);
    Mockito.when(leftCol.getBarcodeMetadata()).thenReturn(null);
    Mockito.when(rightCol.getBarcodeMetadata()).thenReturn(right);

    assertEquals("getBarcodeMetadata should return right when left is null",
        right, invokeGetBarcodeMetadata(leftCol, rightCol));
  }
}

