package com.google.zxing.web;

import org.junit.Assert;
import org.junit.Test;
import org.mockito.MockedStatic;
import org.mockito.Mockito;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.lang.reflect.Method;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

/**
 * Tests {@link DecodeServlet}.
 */
public final class DecodeServletTestCase extends Assert {

  /**
   * Test that images with dimensions large enough to cause integer overflow in
   * height * width are still rejected. 50000 * 50000 = 2,500,000,000 which overflows
   * int to a negative number, bypassing the MAX_PIXELS check if using int arithmetic.
   */
  @Test
  public void testLargeImageOverflow() throws Exception {
    // Create a BufferedImage subclass that reports overflowing dimensions
    final int overflowWidth = 50000;
    final int overflowHeight = 50000;
    BufferedImage image = new BufferedImage(10, 10, BufferedImage.TYPE_INT_RGB) {
      @Override
      public int getWidth() { return overflowWidth; }
      @Override
      public int getHeight() { return overflowHeight; }
    };

    // Verify the image reports the large dimensions
    assertEquals(50000, image.getWidth());
    assertEquals(50000, image.getHeight());

    // Verify the overflow: 50000 * 50000 overflows int to negative
    int product = 50000 * 50000; // = -1794967296 (negative!)
    Assert.assertTrue("Product should overflow to negative", product < 0);

    // Mock ImageIO.read to return our crafted image
    try (MockedStatic<ImageIO> mockedImageIO = Mockito.mockStatic(ImageIO.class)) {
      mockedImageIO.when(() -> ImageIO.read(Mockito.any(InputStream.class))).thenReturn(image);

      HttpServletRequest request = Mockito.mock(HttpServletRequest.class);
      HttpServletResponse response = Mockito.mock(HttpServletResponse.class);

      // Capture the status code set by errorResponse
      final int[] statusCaptured = {-1};
      Mockito.doAnswer(invocation -> {
        statusCaptured[0] = invocation.getArgument(0);
        return null;
      }).when(response).sendError(Mockito.anyInt(), Mockito.anyString());

      // Call processStream via reflection (it's private static)
      Method processStream = DecodeServlet.class.getDeclaredMethod(
          "processStream", InputStream.class,
          HttpServletRequest.class,
          HttpServletResponse.class);
      processStream.setAccessible(true);

      boolean threwNegativeArraySize = false;
      try {
        processStream.invoke(null, new ByteArrayInputStream(new byte[0]), request, response);
      } catch (java.lang.reflect.InvocationTargetException e) {
        if (e.getCause() instanceof NegativeArraySizeException) {
          threwNegativeArraySize = true;
        }
      }

      // The correct behavior: the servlet should reject the oversized image by calling
      // response.sendError(413, "badimage") BEFORE trying to process it.
      //
      // The bug: because `height * width` uses int arithmetic and overflows to
      // a negative number, the check `height * width > MAX_PIXELS` evaluates to
      // false, so the image passes through to processImage(), which then tries to
      // allocate a byte array of size (negative) and crashes with NegativeArraySizeException.
      //
      // So if statusCaptured is still -1 (no error response sent) and we get a
      // NegativeArraySizeException, the bug is present.
      if (threwNegativeArraySize && statusCaptured[0] != HttpServletResponse.SC_REQUEST_ENTITY_TOO_LARGE) {
        fail(
            "Image with dimensions causing int overflow (50000x50000) should be rejected " +
            "with HTTP 413, but instead passed the size check and caused NegativeArraySizeException. " +
            "The height*width overflow bug in DecodeServlet.java:301 allows bypass of MAX_PIXELS limit.");
      }

      assertEquals(
          "Image with dimensions causing int overflow should be rejected as too large (HTTP 413)",
          HttpServletResponse.SC_REQUEST_ENTITY_TOO_LARGE,
          statusCaptured[0]);
    }
  }

}

