      processStream.setAccessible(true);

      boolean threwNegativeArraySize = false;
      try {
        processStream.invoke(null, new ByteArrayInputStream(new byte[0]), request, response);
      } catch (java.lang.reflect.InvocationTargetException e) {
        if (e.getCause() instanceof NegativeArraySizeException) {
          threwNegativeArraySize = true;
        }
      }

      // The correct behavior: the servlet should reject the oversized image by calling
      // response.sendError(413, "badimage") BEFORE trying to process it.
      //
      // The bug: because `height * width` uses int arithmetic and overflows to
      // a negative number, the check `height * width > MAX_PIXELS` evaluates to
      // false, so the image passes through to processImage(), which then tries to
      // allocate a byte array of size (negative) and crashes with NegativeArraySizeException.
      //
      // So if statusCaptured is still -1 (no error response sent) and we get a
      // NegativeArraySizeException, the bug is present.
      if (threwNegativeArraySize && statusCaptured[0] != HttpServletResponse.SC_REQUEST_ENTITY_TOO_LARGE) {
        fail(
            "Image with dimensions causing int overflow (50000x50000) should be rejected " +
            "with HTTP 413, but instead passed the size check and caused NegativeArraySizeException. " +
            "The height*width overflow bug in DecodeServlet.java:301 allows bypass of MAX_PIXELS limit.");
      }

      assertEquals(
          "Image with dimensions causing int overflow should be rejected as too large (HTTP 413)",
          HttpServletResponse.SC_REQUEST_ENTITY_TOO_LARGE,
          statusCaptured[0]);
    }
  }

}

