package com.google.zxing;

import org.junit.Assert;
import org.junit.Test;

import java.awt.image.BufferedImage;

/**
 * Tests {@link InvertedLuminanceSource}.
 */
public final class InvertedLuminanceSourceTestCase extends Assert {

  @Test
  public void testInverted() {
    BufferedImage image = new BufferedImage(2, 1, BufferedImage.TYPE_INT_RGB);
    image.setRGB(0, 0, 0xFFFFFF);
    LuminanceSource source = new BufferedImageLuminanceSource(image);
    assertArrayEquals(new byte[] { (byte) 0xFF, 0 }, source.getRow(0, null));
    LuminanceSource inverted = new InvertedLuminanceSource(source);
    assertArrayEquals(new byte[] { 0, (byte) 0xFF }, inverted.getRow(0, null));
  }

  /**
   * When width and height are large enough that {@code getWidth() * getHeight()} overflows
   * integer range, {@code getMatrix()} should still return the correct result by using the
   * delegate's actual array length rather than computing it from dimensions.
   * 46341 * 46341 = 2,147,488,281 which exceeds Integer.MAX_VALUE and overflows to negative.
   */
  @Test
  public void testGetMatrixWithOverflowDimensions() {
    int overflowWidth = 46341;
    int overflowHeight = 46341;
    int smallArrayLen = 100;

    LuminanceSource delegate = new LuminanceSource(overflowWidth, overflowHeight) {
      @Override
      public byte[] getRow(int y, byte[] row) {
        return new byte[overflowWidth];
      }

      @Override
      public byte[] getMatrix() {
        byte[] data = new byte[smallArrayLen];
        for (int i = 0; i < smallArrayLen; i++) {
          data[i] = (byte) (i & 0xFF);
        }
        return data;
      }
    };

    LuminanceSource inverted = new InvertedLuminanceSource(delegate);
    byte[] result = inverted.getMatrix();

    // The inverted matrix should have the same length as what the delegate returned,
    // not crash or allocate a wrong-sized array due to int overflow in getWidth()*getHeight()
    assertEquals(smallArrayLen, result.length);
    // Values should be inverted: 0->255, 1->254, 2->253, etc.
    for (int i = 0; i < smallArrayLen; i++) {
      assertEquals(255 - (i & 0xFF), result[i] & 0xFF);
    }
  }

}

